/**
 * World-space lock beacons — tightening rings on a painted craft, shatter on unlock.
 */

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Group,
  Mesh,
} from 'three';
import { HEX } from '../core/palette';
import type { Racer } from '../core/types';
import { applyCel, createCelMaterial, nextObjectId } from '../render/celMaterial';

export type LockMark = {
  target: Racer;
  strength: number;
  /** True when the mark is a threat on the local player. */
  incoming: boolean;
};

type Beacon = {
  alive: boolean;
  targetId: number;
  strength: number;
  incoming: boolean;
  spin: number;
  root: Group;
  ringA: Mesh;
  ringB: Mesh;
};

type Burst = {
  alive: boolean;
  age: number;
  life: number;
  x: number;
  y: number;
  z: number;
  root: Group;
};

function ringGeo(r0: number, r1: number, y: number, N = 16): BufferGeometry {
  const positions: number[] = [];
  const normals: number[] = [];
  for (let i = 0; i < N; i++) {
    const a0 = (i / N) * Math.PI * 2;
    const a1 = ((i + 1) / N) * Math.PI * 2;
    const verts = [
      [Math.cos(a0) * r0, y, Math.sin(a0) * r0],
      [Math.cos(a1) * r0, y, Math.sin(a1) * r0],
      [Math.cos(a1) * r1, y, Math.sin(a1) * r1],
      [Math.cos(a0) * r1, y, Math.sin(a0) * r1],
    ] as const;
    for (const tri of [
      [verts[0], verts[1], verts[2]],
      [verts[0], verts[2], verts[3]],
    ]) {
      for (const v of tri) {
        positions.push(v[0], v[1], v[2]);
        normals.push(0, 1, 0);
      }
    }
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  g.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  return g;
}

function makeMat(hex: number, name: string) {
  const color = new Color(hex);
  return createCelMaterial({
    name,
    color,
    rampColors: [
      color.clone().multiplyScalar(0.75),
      color.clone().multiplyScalar(1.05),
      color.clone().multiplyScalar(1.4),
      color.clone().multiplyScalar(1.75),
    ],
    flatShading: true,
    rimColor: new Color(HEX.foam),
    rimPower: 1.5,
    rimStrength: 1,
    outlineWidthPx: 2.8,
    flareMask: 1,
  });
}

export class LockBeaconField {
  private root = new Group();
  private beacons: Beacon[] = [];
  private bursts: Burst[] = [];
  private geoA = ringGeo(1.6, 1.95, 0.06);
  private geoB = ringGeo(2.3, 2.65, 0.08);
  private matOut = makeMat(HEX.hull3, 'lockBeaconOut');
  private matIn = makeMat(HEX.warn, 'lockBeaconIn');
  private matBurst = makeMat(HEX.raceLine, 'lockBurst');
  private ready = false;

  init(scene: { add: (o: Group) => void }) {
    this.root.name = 'lockBeacons';
    scene.add(this.root);
    this.ready = true;
  }

  private allocBeacon(incoming: boolean): Beacon {
    const mats = incoming
      ? { a: this.matIn, b: this.matIn }
      : { a: this.matOut, b: this.matOut };
    const root = new Group();
    const ringA = new Mesh(this.geoA);
    ringA.userData.objectId = nextObjectId();
    applyCel(ringA, mats.a);
    const ringB = new Mesh(this.geoB);
    ringB.userData.objectId = nextObjectId();
    applyCel(ringB, mats.b);
    root.add(ringA);
    root.add(ringB);
    root.visible = false;
    this.root.add(root);
    const b: Beacon = {
      alive: false,
      targetId: -1,
      strength: 0,
      incoming,
      spin: 0,
      root,
      ringA,
      ringB,
    };
    this.beacons.push(b);
    return b;
  }

  update(marks: LockMark[], dt: number, time: number) {
    if (!this.ready) return;
    const used = new Set<number>();
    for (const m of marks) {
      used.add(m.target.id);
      let b = this.beacons.find((x) => x.alive && x.targetId === m.target.id);
      if (!b) {
        b = this.beacons.find((x) => !x.alive) ?? this.allocBeacon(m.incoming);
        b.alive = true;
        b.targetId = m.target.id;
        // Swap materials if threat polarity changed
        if (b.incoming !== m.incoming) {
          applyCel(b.ringA, m.incoming ? this.matIn : this.matOut);
          applyCel(b.ringB, m.incoming ? this.matIn : this.matOut);
        }
      }
      b.incoming = m.incoming;
      b.strength = m.strength;
      b.spin += dt * (1.2 + m.strength * 2.8) * (m.incoming ? -1.4 : 1);
      const p = m.target.state.position;
      const bob = 1.15 + Math.sin(time * 3.2 + m.target.id) * 0.12;
      b.root.visible = true;
      b.root.position.set(p.x, p.y + bob, p.z);
      const tight = 1.15 - m.strength * 0.45;
      b.ringA.scale.setScalar(tight);
      b.ringB.scale.setScalar(tight * (1.25 - m.strength * 0.2));
      b.ringA.rotation.y = b.spin;
      b.ringB.rotation.y = -b.spin * 1.3;
      b.ringA.position.y = 0.05 + m.strength * 0.35;
      b.ringB.position.y = 0.12 + m.strength * 0.2;
    }
    for (const b of this.beacons) {
      if (b.alive && !used.has(b.targetId)) {
        b.alive = false;
        b.root.visible = false;
      }
    }
    for (const u of this.bursts) {
      if (!u.alive) continue;
      u.age += dt;
      const t = u.age / u.life;
      if (t >= 1) {
        u.alive = false;
        u.root.visible = false;
        continue;
      }
      const expand = 0.6 + t * 3.4;
      u.root.position.set(u.x, u.y, u.z);
      u.root.scale.setScalar(expand);
      u.root.rotation.y += dt * 4;
      u.root.visible = true;
    }
  }

  shatterAt(x: number, y: number, z: number) {
    let u = this.bursts.find((b) => !b.alive);
    if (!u) {
      const root = new Group();
      for (let i = 0; i < 3; i++) {
        const mesh = new Mesh(this.geoA);
        mesh.userData.objectId = nextObjectId();
        applyCel(mesh, this.matBurst);
        mesh.rotation.y = (i / 3) * Math.PI * 2;
        root.add(mesh);
      }
      root.visible = false;
      this.root.add(root);
      u = { alive: false, age: 0, life: 0.55, x: 0, y: 0, z: 0, root };
      this.bursts.push(u);
    }
    u.alive = true;
    u.age = 0;
    u.x = x;
    u.y = y + 1.2;
    u.z = z;
    u.root.visible = true;
    u.root.scale.setScalar(0.5);
  }

  dispose() {
    this.root.removeFromParent();
    this.ready = false;
  }
}
