/**
 * Nitro HUD cell — WaveKill ink plate for race overlays.
 */

import { HEX } from '../core/palette';
import { FONT_STACK, inked, inkText, rgba, slantPath } from '../ui/inkDraw';
import { NITRO_DEFAULTS, type NitroHudSnapshot } from './types';

export type NitroHudLayout = {
  x: number;
  y: number;
  w: number;
  h: number;
  scale: number;
  label?: string;
};

export function drawNitroHud(
  g: CanvasRenderingContext2D,
  layout: NitroHudLayout,
  snap: NitroHudSnapshot,
): void {
  const s = layout.scale;
  const { x, y, w, h } = layout;
  const ready = snap.remaining > 0;
  const burning = snap.active > 0;
  const pulse = ready ? 0.55 + 0.45 * Math.sin(snap.readyPulse * 5.5) : 0;
  const flash = Math.min(1, snap.igniteFlash);

  const path = slantPath(x, y, w, h, h * 0.14);
  const fill = burning
    ? rgba(HEX.boostHot, 0.98)
    : ready
      ? rgba(HEX.boost, 0.65 + 0.3 * pulse)
      : rgba(HEX.hudInk, 0.9);
  inked(g, path, fill, rgba(HEX.hudPaper, burning || ready ? 1 : 0.45), 2.6 * s);

  if (flash > 0) {
    g.save();
    g.globalAlpha = flash * 0.9;
    inked(g, path, rgba(HEX.foam, 0.75), rgba(HEX.boostHot, flash), 4 * s);
    g.restore();
  }

  inkText(g, layout.label ?? 'NITRO · N', x + 12 * s, y + 15 * s, {
    font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
    fill: rgba(burning ? HEX.ink : ready ? HEX.hudPaper : HEX.hudDim, 1),
    tracking: 1.6 * s,
  });

  const pipW = 14 * s;
  const pipH = 9 * s;
  const gap = 4 * s;
  const pipY = y + h * 0.52;
  for (let i = 0; i < snap.max; i++) {
    const px = x + 12 * s + i * (pipW + gap);
    const lit = i < snap.remaining || (burning && i === snap.remaining);
    const pip = slantPath(px, pipY, pipW, pipH, pipH * 0.18);
    inked(
      g,
      pip,
      rgba(lit || burning ? HEX.boostHot : HEX.hudInk, 1),
      rgba(HEX.hudPaper, lit || burning ? 1 : 0.35),
      1.6 * s,
    );
  }

  if (burning) {
    const barX = x + 12 * s;
    const barY = y + h - 11 * s;
    const barW = w - 24 * s;
    const barH = 5 * s;
    const frac = Math.min(1, snap.active / NITRO_DEFAULTS.duration);
    g.fillStyle = rgba(HEX.hudInk, 1);
    g.fillRect(barX, barY, barW, barH);
    g.fillStyle = rgba(HEX.boostHot, 1);
    g.fillRect(barX, barY, barW * frac, barH);
    g.strokeStyle = rgba(HEX.hudPaper, 0.7);
    g.lineWidth = 1 * s;
    g.strokeRect(barX, barY, barW, barH);

    inkText(g, 'NITRO', x + w - 12 * s, y + 15 * s, {
      font: `900 ${Math.round(12 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.ink, 1),
      align: 'right',
      tracking: 1.2 * s,
      skew: 0.12,
    });
  } else if (!ready) {
    inkText(g, 'SPENT', x + w - 12 * s, y + 15 * s, {
      font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.hudDim, 0.95),
      align: 'right',
      tracking: 1.5 * s,
    });
  } else {
    inkText(g, 'READY', x + w - 12 * s, y + 15 * s, {
      font: `800 ${Math.round(10 * s)}px ${FONT_STACK}`,
      fill: rgba(HEX.foam, 0.95),
      align: 'right',
      tracking: 1.5 * s,
    });
  }
}
