/**
 * Mobile / touch overlay styles — compact translucent pads, safe-area aware.
 * Designed to stay out of the centre of the track view.
 */

const css = /* css */ `
#touch {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}
#touch .touch-safe {
  position: absolute;
  inset: 0;
  padding:
    max(6px, env(safe-area-inset-top))
    max(8px, env(safe-area-inset-right))
    max(8px, env(safe-area-inset-bottom))
    max(8px, env(safe-area-inset-left));
  pointer-events: none;
}
#touch .touch-steer,
#touch .touch-btn,
#touch .touch-air {
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
}
#touch .touch-steer {
  position: absolute;
  left: max(8px, env(safe-area-inset-left));
  bottom: max(8px, env(safe-area-inset-bottom));
  width: min(28vw, 112px);
  height: min(28vw, 112px);
  border-radius: 50%;
  background: rgba(22, 22, 31, 0.28);
  border: 1.5px solid rgba(30, 240, 240, 0.4);
  box-shadow: none;
}
#touch .touch-steer-ring {
  position: absolute;
  inset: 20%;
  border-radius: 50%;
  border: 1px solid rgba(30, 240, 240, 0.18);
  pointer-events: none;
}
#touch .touch-steer-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 36%;
  height: 36%;
  border-radius: 50%;
  background: rgba(30, 240, 240, 0.55);
  border: 1.5px solid rgba(18, 8, 28, 0.7);
  transform: translate(-50%, -50%);
  box-shadow: none;
  pointer-events: none;
}
#touch .touch-label {
  display: none;
}
#touch .touch-air {
  position: absolute;
  left: max(8px, env(safe-area-inset-left));
  bottom: calc(max(8px, env(safe-area-inset-bottom)) + min(28vw, 112px) + 6px);
  display: flex;
  gap: 5px;
}
#touch .touch-air-btn {
  width: 44px;
  height: 32px;
  font-size: 9px;
  min-height: 32px;
  border-radius: 7px;
  opacity: 0.72;
}
#touch .touch-actions {
  position: absolute;
  right: max(6px, env(safe-area-inset-right));
  bottom: max(8px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(2, minmax(52px, 13vw));
  grid-template-areas:
    "brake brake"
    "boost fire"
    "nitro cam";
  gap: 5px;
  pointer-events: none;
}
#touch .touch-btn {
  pointer-events: auto;
  appearance: none;
  border: 1.5px solid rgba(255, 61, 154, 0.45);
  background: rgba(22, 22, 31, 0.32);
  color: rgba(242, 251, 255, 0.9);
  font: 800 10px/1 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.1em;
  border-radius: 8px;
  min-height: 40px;
  padding: 0 4px;
  text-transform: uppercase;
  opacity: 0.78;
}
#touch .touch-brake {
  grid-area: brake;
  min-height: 42px;
  border-color: rgba(255, 90, 90, 0.55);
  color: #ffc2c2;
}
#touch .touch-boost {
  grid-area: boost;
  border-color: rgba(255, 61, 139, 0.55);
  color: #ffb0d8;
}
#touch .touch-fire {
  grid-area: fire;
  border-color: rgba(255, 201, 60, 0.55);
  color: #ffe08a;
}
#touch .touch-nitro {
  grid-area: nitro;
  border-color: rgba(77, 255, 176, 0.55);
  color: #c4ffe6;
}
#touch .touch-cam {
  grid-area: cam;
  border-color: rgba(106, 142, 200, 0.5);
  color: #cfe0ff;
  min-height: 34px;
}
#touch .touch-btn.is-active,
#touch .touch-steer.is-active {
  opacity: 1;
  background: rgba(255, 61, 154, 0.38);
  box-shadow: 0 0 12px rgba(255, 61, 154, 0.25);
}
#touch .touch-brake.is-active {
  background: rgba(255, 90, 90, 0.42);
}
#touch .touch-fire.is-active {
  background: rgba(255, 201, 60, 0.38);
}
#touch .touch-nitro.is-active {
  background: rgba(77, 255, 176, 0.32);
}
#touch .touch-boost.is-active {
  background: rgba(255, 61, 139, 0.42);
}

@media (orientation: landscape) {
  #touch .touch-steer {
    width: min(22vw, 100px);
    height: min(22vw, 100px);
  }
  #touch .touch-air {
    bottom: calc(max(6px, env(safe-area-inset-bottom)) + min(22vw, 100px) + 5px);
  }
  #touch .touch-actions {
    grid-template-columns: repeat(2, minmax(48px, 11vw));
  }
  #touch .touch-btn { min-height: 36px; font-size: 9px; }
  #touch .touch-brake { min-height: 38px; }
  #touch .touch-cam { min-height: 30px; }
}

@media (max-height: 420px) {
  #touch .touch-steer {
    width: min(20vw, 88px);
    height: min(20vw, 88px);
  }
  #touch .touch-air {
    bottom: calc(max(4px, env(safe-area-inset-bottom)) + min(20vw, 88px) + 4px);
  }
  #touch .touch-air-btn {
    width: 38px;
    height: 28px;
    min-height: 28px;
  }
  #touch .touch-btn { min-height: 32px; font-size: 8px; }
  #touch .touch-brake { min-height: 34px; }
}
`;

let injected = false;
export function injectTouchStyles() {
  if (injected || typeof document === 'undefined') return;
  injected = true;
  const style = document.createElement('style');
  style.id = 'touch-controls-css';
  style.textContent = css;
  document.head.appendChild(style);
}
